def _backfill() -> None:
    """Rows from before M1.10 (pilot data): VAT 5 is standard rated, VAT 0 zero rated on sales and out of scope on
    purchases; priced documents were typed VAT-exclusive; posted invoices get the kind they would get now. The
    guards that keep posted rows permanent are paused for this one-off fill of the new columns only."""
    op.execute("ALTER TABLE document DISABLE TRIGGER document_posted_is_permanent")
    op.execute("ALTER TABLE document_line DISABLE TRIGGER document_line_of_drafts_only")
    op.execute("ALTER TABLE voucher_line DISABLE TRIGGER voucher_line_of_drafts_only")
    op.execute(
        """
        UPDATE document_line l SET tax_code = CASE
            WHEN l.vat_rate > 0 THEN 'SR'
            WHEN d.doc_type IN ('quotation', 'proforma_invoice', 'sales_order', 'delivery_note', 'sales_invoice', 'sales_return') THEN 'ZR'
            ELSE 'OS' END
        FROM document d
        WHERE d.id = l.document_id AND l.vat_rate IS NOT NULL
          AND d.doc_type IN ('quotation', 'proforma_invoice', 'sales_order', 'delivery_note', 'sales_invoice', 'sales_return',
                             'purchase_order', 'goods_receipt', 'purchase_bill', 'purchase_return')
        """
    )
    op.execute(
        """
        UPDATE document SET price_mode = 'vat_exclusive'
        WHERE subtotal IS NOT NULL
          AND doc_type IN ('quotation', 'proforma_invoice', 'sales_order', 'delivery_note', 'sales_invoice', 'sales_return',
                             'purchase_order', 'goods_receipt', 'purchase_bill', 'purchase_return')
        """
    )
    op.execute(
        """
        UPDATE document d SET invoice_kind = CASE
            WHEN NOT b.vat_registered THEN 'invoice'
            WHEN p.trn IS NOT NULL THEN 'tax_invoice'
            ELSE 'simplified' END
        FROM business b, party p
        WHERE b.id = d.business_id AND p.id = d.party_id
          AND d.doc_type IN ('sales_invoice', 'sales_return') AND d.status <> 'draft'
        """
    )
    op.execute(
        """
        UPDATE voucher_line l SET tax_code = 'SR'
        FROM document d
        WHERE d.id = l.document_id AND l.vat_rate > 0
          AND d.doc_type IN ('expense', 'credit_note', 'debit_note')
        """
    )
    op.execute("ALTER TABLE voucher_line ENABLE TRIGGER voucher_line_of_drafts_only")
    op.execute("ALTER TABLE document_line ENABLE TRIGGER document_line_of_drafts_only")
    op.execute("ALTER TABLE document ENABLE TRIGGER document_posted_is_permanent")


